"""Self-contained paired visual review with budget and weak-label limitations."""
import argparse,base64,collections,hashlib,io,json,pathlib,statistics
from PIL import Image


def percentile(values,q):
    values=sorted(values)
    return values[min(len(values)-1,int((len(values)-1)*q))] if values else None


def build(root,plan):
    from openpi.shared.completed_step_memory import CURRENT_TASKS
    samples=[json.loads(x) for x in (root/'samples.jsonl').read_text().splitlines()]
    predictions=[json.loads(x) for x in (root/'predictions.jsonl').read_text().splitlines()]
    references={r['frame_index']:r for r in json.loads((root/'reference-adjudication.json').read_text())['rows']}
    budget=json.loads((root/'budget-ledger.json').read_text());capture=json.loads((root/'capture-provenance.json').read_text())
    models=['gpt-6.2-astra','gpt-6.2-sol'];lookup={(x['model'],x['frame_index']):x for x in predictions}
    completed=lambda x:x and x.get('status')=='completed' and 'prediction' in x
    paired=[s for s in samples if all(completed(lookup.get((m,s['frame_index']))) for m in models)]
    summary={'budget':budget,'capture':capture,'candidate_samples':len(samples),'paired_samples':len(paired),'requests':len(predictions),'models':{},'task_catalog':list(CURRENT_TASKS),'api_image_resolution':[640,480],'image_count_per_request':4,'preview_resolution':[320,240],
      'method':'Independent repair of identical native-loader memory/task inputs per frame. No predictions from another frame or model are fed back. Comparisons use the paired completed intersection. Reference agreement is not independently verified overall task accuracy. Uncertain box-boundary windows excluded from scoring.',
      'references':'Manual current-frame rule overrides stale return labels at frame4880+. Other scored references are human subtask-boundary targets. Bottle-description wording is not scored by exact string.',
      'approved_prompt_hashes':json.loads((root/'approved-prompt-hashes.json').read_text()),'prices_per_million_tokens':{'gpt-6.2-astra':{'input':8,'output':40,'cached':.4,'write_30m':10},'gpt-6.2-sol':{'input':2,'output':10,'cached':.1,'write_30m':2.5}},'reasoning_effort':'low','service_tier':'default','prices_source':'https://developers.openai.com/api/docs/pricing'}
    scored=[s for s in paired if references[s['frame_index']]['task_reference_index'] is not None]
    summary['paired_scored_samples']=len(scored)
    for model in models:
        own=[x for x in predictions if x['model']==model];good=[x for x in own if completed(x)];lat=[x['latency_seconds'] for x in good]
        taskhits=sum(lookup[(model,s['frame_index'])]['prediction']['current_task_index']==references[s['frame_index']]['task_reference_index'] for s in scored)
        memhits=sum(lookup[(model,s['frame_index'])]['prediction']['memory']==references[s['frame_index']]['memory_reference'] for s in scored)
        strata={}
        for md,td in [(False,False),(True,False),(False,True),(True,True)]:
            part=[s for s in scored if bool(s['augmentation']['memory_dropout_applied'])==md and bool(s['augmentation']['subtask_dropout_applied'])==td]
            strata[f'memory_{int(md)}_task_{int(td)}']={'n':len(part),'task_matches':sum(lookup[(model,s['frame_index'])]['prediction']['current_task_index']==references[s['frame_index']]['task_reference_index'] for s in part),'memory_matches':sum(lookup[(model,s['frame_index'])]['prediction']['memory']==references[s['frame_index']]['memory_reference'] for s in part)}
        reset=[s for s in paired if s['frame_index']>=4880]
        summary['models'][model]={'requests':len(own),'completed':len(good),'errors':len(own)-len(good),'known_cost_usd':sum(x.get('cost_usd') or 0 for x in own),
          'latency_p50_seconds':percentile(lat,.5),'latency_p95_seconds':percentile(lat,.95),'paired_scored_n':len(scored),'task_reference_matches':taskhits,'task_reference_match_rate':taskhits/len(scored) if scored else None,'memory_exact_reference_matches':memhits,'memory_exact_match_rate':memhits/len(scored) if scored else None,'strata':strata,
          'post_box_departure_cases':len(reset),'post_box_departure_task1':sum(lookup[(model,s['frame_index'])]['prediction']['current_task_index']==1 for s in reset),'post_box_departure_memory_cleared':sum(lookup[(model,s['frame_index'])]['prediction']['memory']=='' for s in reset)}
    summary['models_task_agreement']=sum(lookup[(models[0],s['frame_index'])]['prediction']['current_task_index']==lookup[(models[1],s['frame_index'])]['prediction']['current_task_index'] for s in paired)
    images={}
    for sample in samples:
        sample['reference']=references[sample['frame_index']]
        sample['results']={m:lookup.get((m,sample['frame_index'])) for m in models}
        for path in sample['images'].values():
            im=Image.open(root/path).convert('RGB');im.thumbnail((320,240));buf=io.BytesIO();im.save(buf,format='WEBP',quality=78)
            images[path]='data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()
    payload=json.dumps({'samples':samples,'summary':summary,'images':images,'prompt_en':(plan/'prompt-en.txt').read_text(),'prompt_zh':(plan/'prompt-zh.txt').read_text(),'schema':json.loads((plan/'output-schema.json').read_text())},ensure_ascii=False).replace('</',r'<\/')
